<script setup lang="ts">import {ref} from 'vue';import type {Candidate} from '../api/contracts';import ModalDialog from './ModalDialog.vue';defineProps<{candidates:Candidate[];count:number;busy:boolean}>();defineEmits<{confirm:[reason:string];cancel:[]}>();const reason=ref('');</script>
<template><ModalDialog :busy="busy" title="重複候補の確認" label-id="duplicate-title" data-field-id="REG-032" @cancel="$emit('cancel')"><p>同じ学生の可能性があります。別人であることを確認してください。</p><p>全候補{{count}}件、最大20件を表示します。</p><div class="candidate-list" tabindex="0"><table><thead><tr><th>学籍番号</th><th>氏名</th><th>生年月日</th><th>クラス</th></tr></thead><tbody><tr v-for="c in candidates.slice(0,20)" :key="c.studentId"><td>{{c.studentNo}}</td><td>{{c.studentName}}</td><td>{{c.birthDateWareki}}</td><td>{{c.classLabel}}</td></tr></tbody></table></div><label>確認理由（必須・60文字以内）<textarea v-model="reason" maxlength="120"></textarea></label><div class="dialog-actions"><button type="button" data-cancel data-field-id="REG-034" :disabled="busy" @click="$emit('cancel')">取消</button><button type="button" class="primary" data-field-id="REG-033" :disabled="busy||!reason.trim()" @click="$emit('confirm',reason)">別人と確認して続行</button></div></ModalDialog></template>
